package com.coraline.client;
import com.coraline.tycoon.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.*;
import net.minecraft.client.gui.components.*;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import java.util.*;
public final class TycoonScreen extends Screen {
    private CompoundTag data;private String tab="Overview";private int page;private int left,top,w,h;
    private TycoonScreen(CompoundTag n){super(Component.literal(n.getString("Mode").equals("debug")?"Coraline Tycoon — Phase 1 Debugger":"World Weaver Ledger"));data=n;}
    public static void receive(CompoundTag n){if(n==null)return;if(n.getString("Mode").equals("food_state")){TycoonFoodOverlay.receive(n);return;}if(n.getString("Mode").equals("world_visuals")){TycoonWorldClientState.receive(n);return;}if(n.getString("Mode").equals("worlddesk")||n.getString("Mode").equals("debug2")||n.getString("Mode").equals("fooddebug")){TycoonWorldScreen.receive(n);return;}if(n.getString("Mode").equals("visitor")){TycoonConversationScreen.receive(n);return;}var mc=Minecraft.getInstance();if(mc.screen instanceof TycoonScreen s){s.data=n;s.rebuildWidgets();}else mc.setScreen(new TycoonScreen(n));}
    @Override public boolean isPauseScreen(){return false;}
    private void send(String action,String value){TycoonNetwork.action(data.getUUID("Nonce"),action,value);}
    private void button(String label,int x,int y,int width,Runnable action){addRenderableWidget(Button.builder(Component.literal(label),b->action.run()).bounds(x,y,width,20).build());}
    @Override protected void init(){w=Math.min(520,width-16);h=Math.min(340,height-16);left=(width-w)/2;top=(height-h)/2;String mode=data.getString("Mode");var tabs=mode.equals("debug")?List.of("Debug"):mode.equals("child")?List.of("Resident"):mode.equals("desk")?List.of("Overview","Upgrades","Progression","Residents","World"):List.of("Overview","Placements","Residents");for(int i=0;i<tabs.size();i++){String t=tabs.get(i);button(t,left+10+i*(w-20)/tabs.size(),top+27,(w-24)/tabs.size(),()->{tab=t;page=0;rebuildWidgets();});}if(mode.equals("debug"))tab="Debug";if(mode.equals("child"))tab="Resident";button("Refresh",left+10,top+h-30,65,()->send("refresh",""));button("Close",left+w-75,top+h-30,65,this::onClose);
        if(tab.equals("Overview")){if(mode.equals("desk"))button(data.getBoolean("PhoneIssued")?"Phone already issued":"Claim free Orphanage Phone",left+15,top+h-65,w-30,()->send("phone",""));else{button("Contact agency",left+15,top+h-65,(w-40)/2,()->send("agency",""));button("Request inspection",left+25+(w-40)/2,top+h-65,(w-40)/2,()->send("inspect",""));}}
        if(tab.equals("World"))button("Dolls / World / Visits / Other World Food",left+15,top+92,w-30,()->send("phase2",""));
        if(tab.equals("Upgrades")){var list=data.getList("Shop",10);int rows=Math.max(1,Math.min(6,(h-130)/25));for(int i=page*rows;i<Math.min(list.size(),page*rows+rows);i++){var row=list.getCompound(i);button(row.getString("Name")+" — "+row.getInt("Cost")+" Void Power",left+15,top+78+(i%rows)*25,w-30,()->send("buy",row.getString("Id")));}pages(list.size(),rows);}
        if(tab.equals("Placements")){var list=data.getList("Candidates",10);if(!list.isEmpty()){page=Math.min(page,list.size()-1);var row=list.getCompound(page);button("Accept placement — "+row.getInt("Fee")+" emeralds",left+15,top+h-65,w-30,()->send("place",row.getUUID("Id").toString()));}pages(list.size(),1);}
        if(tab.equals("Residents"))pages(data.getList("Residents",10).size(),Math.max(1,(h-145)/32));
        if(tab.equals("Resident")){String[] actions={"accept","decline","give","forgive","punish"};int rows=Math.max(1,Math.min(5,(h-166)/24));for(int i=page*rows;i<Math.min(actions.length,page*rows+rows);i++){String action=actions[i];button(action.equals("punish")?"Assign cleanup (nonviolent)":TycoonContent.label(action),left+15,top+115+(i%rows)*24,w-30,()->send("child",action));}pages(actions.length,rows);}
        if(tab.equals("Debug")){var controls=data.getList("DebugControls",10);int rows=Math.max(1,Math.min(7,(h-120)/25));for(int i=page*rows;i<Math.min(controls.size(),page*rows+rows);i++){var row=controls.getCompound(i);button(row.getString("Label"),left+15,top+65+(i%rows)*25,w-30,()->send("debug",row.getString("Action")));}pages(controls.size(),rows);}
    }
    private void pages(int size,int perPage){if(size<=perPage)return;button("<",left+w/2-50,top+h-30,35,()->{page=Math.max(0,page-1);rebuildWidgets();});button(">",left+w/2+15,top+h-30,35,()->{page=Math.min((size-1)/perPage,page+1);rebuildWidgets();});}
    @Override public void render(GuiGraphics g,int mx,int my,float partial){renderBackground(g);g.fill(left,top,left+w,top+h,0xF0181424);g.fill(left+2,top+2,left+w-2,top+23,0xFF493452);g.drawCenteredString(font,title,left+w/2,top+8,0xF1D9AC);g.drawString(font,"Void Power "+data.getInt("VoidPower")+"  |  Soul Essence "+data.getLong("SoulEssence")+"  |  Level "+data.getInt("Level"),left+12,top+53,0xC9A9EB,false);
        if(tab.equals("Overview")){int y=top+78;for(var line:data.getList("Lines",8)){for(var part:font.split(Component.literal(line.getAsString()),w-30)){if(y>top+h-80)break;g.drawString(font,part,left+15,y,0xE1D8CE);y+=12;}}}
        if(tab.equals("Progression")){g.drawString(font,"Permanent XP: "+data.getInt("XP")+" — milestones only",left+15,top+85,0xE1D8CE);g.drawString(font,"Agency reputation: "+data.getInt("Reputation")+" / 100",left+15,top+110,0xE1D8CE);g.drawString(font,"Starter / completed-visit Soul Essence funds food; conversion stays future.",left+15,top+140,0xA8A0B4);}
        if(tab.equals("Residents")){int y=top+80;var list=data.getList("Residents",10);int rows=Math.max(1,(h-145)/32);for(int i=page*rows;i<Math.min(list.size(),page*rows+rows);i++){var r=list.getCompound(i);g.drawString(font,font.plainSubstrByWidth(r.getString("Name")+" — "+r.getString("Status")+" / "+r.getString("Task"),w-30),left+15,y,0xE1D8CE);g.drawString(font,"Food "+r.getInt("Hunger")+" Water "+r.getInt("Thirst")+" Neglect "+r.getInt("Neglect")+" Comfort "+r.getInt("Comfort"),left+15,y+13,0xADA7B9);y+=32;}}
        if(tab.equals("Placements")){var pool=data.getList("Candidates",10);if(!pool.isEmpty()){var r=pool.getCompound(Math.min(page,pool.size()-1));g.drawString(font,r.getString("Name")+", age "+r.getInt("Age"),left+15,top+83,0xF1D9AC);int y=top+106;for(var line:font.split(Component.literal(r.getString("Personality")),w-100)){g.drawString(font,line,left+15,y,0xD8CBDD);y+=12;}preview(g,left+w-60,top+125,r.getInt("Appearance"));g.drawString(font,"Next placement: "+data.getLong("Cooldown")/1200+" active min",left+15,top+170,0xC4B1D7);}}
        if(tab.equals("Resident")){g.drawString(font,data.getString("ChildName"),left+15,top+73,0xF1D9AC);g.drawString(font,"Request: "+data.getString("Request")+" "+data.getString("Wanted"),left+15,top+86,0xD8CBDD);g.drawString(font,data.getString("Incident"),left+15,top+99,0xD8CBDD);}
        String result=data.getString("Result");if(!result.isEmpty())g.drawString(font,font.plainSubstrByWidth(result,w-30),left+15,top+h-43,0xE8C581);super.render(g,mx,my,partial);
    }
    private static void preview(GuiGraphics g,int x,int y,int seed){int skin=new int[]{0xFFE1B994,0xFFBA845E,0xFF835C43,0xFFF1D2BA,0xFFA66D4B}[(seed/5)%5],hair=new int[]{0xFF392A25,0xFFBB8139,0xFF251F25,0xFF77482D,0xFFD8C39E}[(seed/25)%5];g.fill(x-18,y-38,x+18,y+3,skin);g.fill(x-20,y-40,x+20,y-28,hair);if((seed/750)%4>0){g.fill(x-22,y-30,x-15,y+5,hair);g.fill(x+15,y-30,x+22,y+5,hair);}g.fill(x-11,y-17,x-7,y-10,0xFF222633);g.fill(x+7,y-17,x+11,y-10,0xFF222633);g.fill(x-5,y-3,x+5,y-1,0xFF6B453D);}
}
